insert into kairo.questions (id, subject, topic, subtopic, learning_objective, concepts_tested, difficulty_rating, cognitive_level, estimated_solving_time_sec, reading_load, calculation_load, distractors, source, exam_body, stem, options, correct_option, explanation, lifecycle_state, distractor_rationale) values
($q$mathematics_0001$q$, $q$Mathematics$q$, $q$Number Bases$q$, $q$Base Conversion$q$, $q$Convert a binary (base two) number to base ten by place value.$q$, $q$[{"conceptId": "be64x9", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 45, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "This results from assigning place values in reverse order (treating the leftmost digit as 2\u2070 instead of the rightmost).", "misconceptionId": "formula_recall_error"}, {"option": "C", "explanation": "An arithmetic slip while adding the place values (32+16+4+1) gives 53, not 54.", "misconceptionId": "arithmetic_slip"}, {"option": "D", "explanation": "This omits the 2\u2074 (16) place value from the sum.", "misconceptionId": "formula_recall_error"}]$q$::jsonb, $q$techmed_authored$q$, $q$JAMB$q$, $q$Convert 110101₂ to base 10.$q$, $q$[{"label": "A", "text": "43", "isCorrect": false}, {"label": "B", "text": "53", "isCorrect": true}, {"label": "C", "text": "54", "isCorrect": false}, {"label": "D", "text": "37", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$Each digit's place value doubles moving left: 110101₂ = (1×32)+(1×16)+(0×8)+(1×4)+(0×2)+(1×1) = 32+16+0+4+0+1 = 53.$q$, $q$live$q$, $q$A: This results from assigning place values in reverse order (treating the leftmost digit as 2⁰ instead of the rightmost). C: An arithmetic slip while adding the place values (32+16+4+1) gives 53, not 54. D: This omits the 2⁴ (16) place value from the sum.$q$),
($q$mathematics_0002$q$, $q$Mathematics$q$, $q$Number Bases$q$, $q$Base Conversion$q$, $q$Convert a base ten number to binary using repeated division by 2.$q$, $q$[{"conceptId": "be64x9", "weight": 1}]$q$::jsonb, 3, $q$application$q$, 60, $q$low$q$, $q$moderate$q$, $q$[{"option": "A", "explanation": "This is the binary representation of 53, not 58 \u2014 an error occurred in one of the division steps.", "misconceptionId": "arithmetic_slip"}, {"option": "C", "explanation": "This equals 60 in decimal, not 58 \u2014 likely from writing an extra remainder digit.", "misconceptionId": "arithmetic_slip"}, {"option": "D", "explanation": "This equals 42 in decimal \u2014 the repeated-digit pattern looks similar to the correct answer but corresponds to a different value.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$techmed_authored$q$, $q$JAMB$q$, $q$Convert 58 (base 10) to base 2.$q$, $q$[{"label": "A", "text": "110101", "isCorrect": false}, {"label": "B", "text": "111010", "isCorrect": true}, {"label": "C", "text": "111100", "isCorrect": false}, {"label": "D", "text": "101010", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$Dividing repeatedly by 2: 58=29r0, 29=14r1, 14=7r0, 7=3r1, 3=1r1, 1=0r1. Reading the remainders from bottom to top gives 111010.$q$, $q$live$q$, $q$A: This is the binary representation of 53, not 58 — an error occurred in one of the division steps. C: This equals 60 in decimal, not 58 — likely from writing an extra remainder digit. D: This equals 42 in decimal — the repeated-digit pattern looks similar to the correct answer but corresponds to a different value.$q$),
($q$mathematics_0003$q$, $q$Mathematics$q$, $q$Number Bases$q$, $q$Base Conversion$q$, $q$Convert a number in another base (base eight) to base ten by place value.$q$, $q$[{"conceptId": "be64x9", "weight": 1}]$q$::jsonb, 3, $q$application$q$, 60, $q$low$q$, $q$moderate$q$, $q$[{"option": "A", "explanation": "This is only the 2\u00d78\u00b2 term \u2014 the 3\u00d78\u00b9 and 5\u00d78\u2070 terms were left out of the sum.", "misconceptionId": "formula_recall_error"}, {"option": "C", "explanation": "This treats the digits as already being in base ten, without converting from base eight at all.", "misconceptionId": "misunderstood_terminology"}, {"option": "D", "explanation": "An arithmetic slip while adding the place values gives 157, not 141.", "misconceptionId": "arithmetic_slip"}]$q$::jsonb, $q$techmed_authored$q$, $q$JAMB$q$, $q$Evaluate 235₈ (base eight) in base ten.$q$, $q$[{"label": "A", "text": "128", "isCorrect": false}, {"label": "B", "text": "157", "isCorrect": true}, {"label": "C", "text": "235", "isCorrect": false}, {"label": "D", "text": "141", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$235₈ = (2×8²)+(3×8¹)+(5×8⁰) = 128+24+5 = 157.$q$, $q$live$q$, $q$A: This is only the 2×8² term — the 3×8¹ and 5×8⁰ terms were left out of the sum. C: This treats the digits as already being in base ten, without converting from base eight at all. D: An arithmetic slip while adding the place values gives 157, not 141.$q$),
($q$mathematics_0004$q$, $q$Mathematics$q$, $q$Indices and Logarithms$q$, $q$Laws of Indices and Logarithms$q$, $q$Apply the laws of indices to simplify expressions with the same base.$q$, $q$[{"conceptId": "q380e4", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 40, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "An off-by-one slip in combining the exponents gives 2\u00b9=2 instead of 2\u00b2=4.", "misconceptionId": "arithmetic_slip"}, {"option": "C", "explanation": "An off-by-one slip the other way gives 2\u00b3=8 instead of 2\u00b2=4.", "misconceptionId": "arithmetic_slip"}, {"option": "D", "explanation": "This is 2\u2075, the value of the divisor itself, not the simplified result.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$techmed_authored$q$, $q$JAMB$q$, $q$Simplify (2³ × 2⁴) ÷ 2⁵.$q$, $q$[{"label": "A", "text": "2", "isCorrect": false}, {"label": "B", "text": "4", "isCorrect": true}, {"label": "C", "text": "8", "isCorrect": false}, {"label": "D", "text": "32", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$2³×2⁴÷2⁵ = 2^(3+4−5) = 2² = 4.$q$, $q$live$q$, $q$A: An off-by-one slip in combining the exponents gives 2¹=2 instead of 2²=4. C: An off-by-one slip the other way gives 2³=8 instead of 2²=4. D: This is 2⁵, the value of the divisor itself, not the simplified result.$q$),
($q$mathematics_0005$q$, $q$Mathematics$q$, $q$Indices and Logarithms$q$, $q$Laws of Indices and Logarithms$q$, $q$Understand a logarithm as the inverse of an exponent.$q$, $q$[{"conceptId": "q380e4", "weight": 1}]$q$::jsonb, 1, $q$recall$q$, 30, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "This is log\u20824, not log\u20828.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "2\u2074=16, not 8 \u2014 this overshoots the correct exponent.", "misconceptionId": "arithmetic_slip"}, {"option": "D", "explanation": "This confuses the logarithm's value with the original number itself.", "misconceptionId": "misunderstood_terminology"}]$q$::jsonb, $q$techmed_authored$q$, $q$JAMB$q$, $q$If log₂8 = x, find x.$q$, $q$[{"label": "A", "text": "2", "isCorrect": false}, {"label": "B", "text": "3", "isCorrect": true}, {"label": "C", "text": "4", "isCorrect": false}, {"label": "D", "text": "8", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$log₂8 = x means 2^x = 8 = 2³, so x = 3.$q$, $q$live$q$, $q$A: This is log₂4, not log₂8. C: 2⁴=16, not 8 — this overshoots the correct exponent. D: This confuses the logarithm's value with the original number itself.$q$),
($q$mathematics_0006$q$, $q$Mathematics$q$, $q$Indices and Logarithms$q$, $q$Laws of Indices and Logarithms$q$, $q$Apply the addition law of logarithms (log a + log b = log ab) with base-ten logarithms.$q$, $q$[{"conceptId": "q380e4", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 45, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "This is log\u2081\u2080100 alone \u2014 the second term, log\u2081\u208010, was left out.", "misconceptionId": "formula_recall_error"}, {"option": "C", "explanation": "This is log\u2081\u208010 alone \u2014 the first term, log\u2081\u2080100, was left out.", "misconceptionId": "formula_recall_error"}, {"option": "D", "explanation": "This multiplies the original numbers (100\u00d710=1000) instead of adding their logarithms.", "misconceptionId": "overgeneralized_rule"}]$q$::jsonb, $q$techmed_authored$q$, $q$JAMB$q$, $q$Evaluate log₁₀100 + log₁₀10.$q$, $q$[{"label": "A", "text": "2", "isCorrect": false}, {"label": "B", "text": "3", "isCorrect": true}, {"label": "C", "text": "1", "isCorrect": false}, {"label": "D", "text": "1000", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$log₁₀100 = 2 and log₁₀10 = 1, so the sum is 2+1 = 3.$q$, $q$live$q$, $q$A: This is log₁₀100 alone — the second term, log₁₀10, was left out. C: This is log₁₀10 alone — the first term, log₁₀100, was left out. D: This multiplies the original numbers (100×10=1000) instead of adding their logarithms.$q$),
($q$mathematics_0007$q$, $q$Mathematics$q$, $q$Simultaneous Equations$q$, $q$Linear Equations in Two Variables$q$, $q$Solve a pair of linear simultaneous equations using the elimination method.$q$, $q$[{"conceptId": "nfvo16", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 50, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "This is the value of y, not x.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "This comes from adding 2 to x=6 instead of using it directly \u2014 an arithmetic slip.", "misconceptionId": "arithmetic_slip"}, {"option": "D", "explanation": "This is half of 10, from incorrectly assuming x=y before solving.", "misconceptionId": "overgeneralized_rule"}]$q$::jsonb, $q$techmed_authored$q$, $q$JAMB$q$, $q$If x + y = 10 and x − y = 2, find the value of x.$q$, $q$[{"label": "A", "text": "4", "isCorrect": false}, {"label": "B", "text": "6", "isCorrect": true}, {"label": "C", "text": "8", "isCorrect": false}, {"label": "D", "text": "5", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$Adding the two equations: (x+y)+(x−y) = 10+2 → 2x = 12 → x = 6.$q$, $q$live$q$, $q$A: This is the value of y, not x. C: This comes from adding 2 to x=6 instead of using it directly — an arithmetic slip. D: This is half of 10, from incorrectly assuming x=y before solving.$q$),
($q$mathematics_0008$q$, $q$Mathematics$q$, $q$Simultaneous Equations$q$, $q$Linear Equations in Two Variables$q$, $q$Solve simultaneous equations using substitution.$q$, $q$[{"conceptId": "nfvo16", "weight": 1}]$q$::jsonb, 3, $q$application$q$, 65, $q$low$q$, $q$moderate$q$, $q$[{"option": "A", "explanation": "This is the constant from x \u2212 y = 1, not the value of y.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "This is the value of x, not y.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "This results from dividing 12 by 3 directly, ignoring the x-term in the equation.", "misconceptionId": "overgeneralized_rule"}]$q$::jsonb, $q$techmed_authored$q$, $q$JAMB$q$, $q$Given 2x + 3y = 12 and x − y = 1, find the value of y.$q$, $q$[{"label": "A", "text": "1", "isCorrect": false}, {"label": "B", "text": "2", "isCorrect": true}, {"label": "C", "text": "3", "isCorrect": false}, {"label": "D", "text": "4", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$From x − y = 1, x = y+1. Substituting: 2(y+1) + 3y = 12 → 5y + 2 = 12 → 5y = 10 → y = 2.$q$, $q$live$q$, $q$A: This is the constant from x − y = 1, not the value of y. C: This is the value of x, not y. D: This results from dividing 12 by 3 directly, ignoring the x-term in the equation.$q$),
($q$mathematics_0009$q$, $q$Mathematics$q$, $q$Simultaneous Equations$q$, $q$Linear Equations in Two Variables$q$, $q$Solve simultaneous equations and use the results to evaluate a related expression.$q$, $q$[{"conceptId": "nfvo16", "weight": 1}]$q$::jsonb, 3, $q$application$q$, 70, $q$low$q$, $q$moderate$q$, $q$[{"option": "A", "explanation": "This is x+y, the sum already given in the problem \u2014 not the product xy.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "This is the value of x alone \u2014 the multiplication by y was left out.", "misconceptionId": "formula_recall_error"}, {"option": "D", "explanation": "This is the value of y alone \u2014 the multiplication by x was left out.", "misconceptionId": "formula_recall_error"}]$q$::jsonb, $q$techmed_authored$q$, $q$JAMB$q$, $q$If 3x − y = 7 and x + y = 5, find the value of xy.$q$, $q$[{"label": "A", "text": "5", "isCorrect": false}, {"label": "B", "text": "6", "isCorrect": true}, {"label": "C", "text": "3", "isCorrect": false}, {"label": "D", "text": "2", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$Adding the equations: (3x−y)+(x+y) = 7+5 → 4x = 12 → x = 3. Then y = 5−3 = 2, so xy = 3×2 = 6.$q$, $q$live$q$, $q$A: This is x+y, the sum already given in the problem — not the product xy. C: This is the value of x alone — the multiplication by y was left out. D: This is the value of y alone — the multiplication by x was left out.$q$),
($q$mathematics_0010$q$, $q$Mathematics$q$, $q$Quadratic Equations$q$, $q$Factorization Method$q$, $q$Solve a quadratic equation by factorization.$q$, $q$[{"conceptId": "p719da", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 55, $q$low$q$, $q$light$q$, $q$[{"option": "B", "explanation": "This uses the wrong sign \u2014 the factors (x\u22122)(x\u22123) give x=2 and x=3, not their negatives.", "misconceptionId": "sign_error"}, {"option": "C", "explanation": "1\u00d76=6 correctly matches the constant term, but 1+6=7 does not match the coefficient 5, so this is not a valid factor pair.", "misconceptionId": "formula_recall_error"}, {"option": "D", "explanation": "This mixes the correct root x=2 with an incorrect sign on the second root.", "misconceptionId": "sign_error"}]$q$::jsonb, $q$techmed_authored$q$, $q$JAMB$q$, $q$Solve the equation x² − 5x + 6 = 0.$q$, $q$[{"label": "A", "text": "x=2 or x=3", "isCorrect": true}, {"label": "B", "text": "x=\u22122 or x=\u22123", "isCorrect": false}, {"label": "C", "text": "x=1 or x=6", "isCorrect": false}, {"label": "D", "text": "x=2 or x=\u22123", "isCorrect": false}]$q$::jsonb, $q$A$q$, $q$x² − 5x + 6 factorizes as (x−2)(x−3) = 0, so x = 2 or x = 3.$q$, $q$live$q$, $q$B: This uses the wrong sign — the factors (x−2)(x−3) give x=2 and x=3, not their negatives. C: 1×6=6 correctly matches the constant term, but 1+6=7 does not match the coefficient 5, so this is not a valid factor pair. D: This mixes the correct root x=2 with an incorrect sign on the second root.$q$),
($q$mathematics_0011$q$, $q$Mathematics$q$, $q$Quadratic Equations$q$, $q$Factorization Method$q$, $q$Solve a quadratic equation by factorization and select the required root.$q$, $q$[{"conceptId": "p719da", "weight": 1}]$q$::jsonb, 3, $q$application$q$, 60, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "This is the magnitude of the negative root, not the positive root itself (the negative root is \u22123).", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "This is the constant term of the equation, not a root.", "misconceptionId": "misunderstood_terminology"}, {"option": "D", "explanation": "This is the negative root \u2014 a rushed read of 'positive root' selects the correct equation but the wrong sign.", "misconceptionId": "rushed_under_pressure"}]$q$::jsonb, $q$techmed_authored$q$, $q$JAMB$q$, $q$Find the positive root of x² − 2x − 15 = 0.$q$, $q$[{"label": "A", "text": "3", "isCorrect": false}, {"label": "B", "text": "5", "isCorrect": true}, {"label": "C", "text": "15", "isCorrect": false}, {"label": "D", "text": "\u22123", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$x² − 2x − 15 factorizes as (x−5)(x+3) = 0, giving x = 5 or x = −3. The positive root is 5.$q$, $q$live$q$, $q$A: This is the magnitude of the negative root, not the positive root itself (the negative root is −3). C: This is the constant term of the equation, not a root. D: This is the negative root — a rushed read of 'positive root' selects the correct equation but the wrong sign.$q$),
($q$mathematics_0012$q$, $q$Mathematics$q$, $q$Quadratic Equations$q$, $q$Factorization Method$q$, $q$Use the coefficients of a quadratic equation to find the sum or product of its roots without solving explicitly.$q$, $q$[{"conceptId": "p719da", "weight": 1}]$q$::jsonb, 3, $q$recall$q$, 50, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "This is the sum of the roots (\u2212b/a = 7), not the product.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "This is the negative of the coefficient of x, not the product of the roots.", "misconceptionId": "formula_recall_error"}, {"option": "D", "explanation": "This has the correct magnitude but the wrong sign \u2014 the product of roots is c/a = 12/1 = 12, positive since c and a share the same sign.", "misconceptionId": "sign_error"}]$q$::jsonb, $q$techmed_authored$q$, $q$JAMB$q$, $q$For the equation x² − 7x + 12 = 0, what is the product of its roots?$q$, $q$[{"label": "A", "text": "7", "isCorrect": false}, {"label": "B", "text": "12", "isCorrect": true}, {"label": "C", "text": "\u22127", "isCorrect": false}, {"label": "D", "text": "\u221212", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$For ax²+bx+c=0, the product of the roots is c/a. Here c=12, a=1, so the product is 12 (the roots are 3 and 4, and 3×4=12).$q$, $q$live$q$, $q$A: This is the sum of the roots (−b/a = 7), not the product. C: This is the negative of the coefficient of x, not the product of the roots. D: This has the correct magnitude but the wrong sign — the product of roots is c/a = 12/1 = 12, positive since c and a share the same sign.$q$),
($q$mathematics_0013$q$, $q$Mathematics$q$, $q$Simple Interest and Percentages$q$, $q$Percentage Change and Simple Interest$q$, $q$Apply the simple interest formula I = PRT/100.$q$, $q$[{"conceptId": "46gg3b", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 60, $q$low$q$, $q$moderate$q$, $q$[{"option": "A", "explanation": "This uses only 1 year instead of 3 in the calculation.", "misconceptionId": "formula_recall_error"}, {"option": "C", "explanation": "This treats the rate (5) as a direct multiple of 1000 rather than applying the simple interest formula correctly.", "misconceptionId": "arithmetic_slip"}, {"option": "D", "explanation": "This forgets to divide by 100, giving a figure 100 times too large.", "misconceptionId": "formula_recall_error"}]$q$::jsonb, $q$techmed_authored$q$, $q$JAMB$q$, $q$Find the simple interest on ₦20,000 for 3 years at 5% per annum.$q$, $q$[{"label": "A", "text": "\u20a61,000", "isCorrect": false}, {"label": "B", "text": "\u20a63,000", "isCorrect": true}, {"label": "C", "text": "\u20a65,000", "isCorrect": false}, {"label": "D", "text": "\u20a630,000", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$Simple Interest = (P×R×T)/100 = (20000×5×3)/100 = 300000/100 = ₦3,000.$q$, $q$live$q$, $q$A: This uses only 1 year instead of 3 in the calculation. C: This treats the rate (5) as a direct multiple of 1000 rather than applying the simple interest formula correctly. D: This forgets to divide by 100, giving a figure 100 times too large.$q$),
($q$mathematics_0014$q$, $q$Mathematics$q$, $q$Simple Interest and Percentages$q$, $q$Percentage Change and Simple Interest$q$, $q$Calculate a percentage increase relative to the original value.$q$, $q$[{"conceptId": "46gg3b", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 55, $q$low$q$, $q$moderate$q$, $q$[{"option": "A", "explanation": "This divides the increase by the new price (800/4800) instead of the original price.", "misconceptionId": "formula_recall_error"}, {"option": "C", "explanation": "This uses the wrong base for the division, giving an inflated percentage.", "misconceptionId": "arithmetic_slip"}, {"option": "D", "explanation": "This treats 800 as a percentage of 1000 rather than as a percentage of the original price, 4000.", "misconceptionId": "formula_recall_error"}]$q$::jsonb, $q$techmed_authored$q$, $q$JAMB$q$, $q$A trader increases the price of an item from ₦4,000 to ₦4,800. Find the percentage increase.$q$, $q$[{"label": "A", "text": "16.7%", "isCorrect": false}, {"label": "B", "text": "20%", "isCorrect": true}, {"label": "C", "text": "25%", "isCorrect": false}, {"label": "D", "text": "80%", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$Percentage increase = (increase/original) × 100 = (800/4000) × 100 = 20%.$q$, $q$live$q$, $q$A: This divides the increase by the new price (800/4800) instead of the original price. C: This uses the wrong base for the division, giving an inflated percentage. D: This treats 800 as a percentage of 1000 rather than as a percentage of the original price, 4000.$q$),
($q$mathematics_0015$q$, $q$Mathematics$q$, $q$Simple Interest and Percentages$q$, $q$Percentage Change and Simple Interest$q$, $q$Work backward from a simple interest amount to find the original principal.$q$, $q$[{"conceptId": "46gg3b", "weight": 1}]$q$::jsonb, 4, $q$application$q$, 90, $q$medium$q$, $q$heavy$q$, $q$[{"option": "A", "explanation": "This divides 33,000 by an incorrect growth factor of 1.32 instead of 1.2.", "misconceptionId": "arithmetic_slip"}, {"option": "C", "explanation": "This assumes only 10% total growth instead of 20% (10% \u00d7 2 years).", "misconceptionId": "formula_recall_error"}, {"option": "D", "explanation": "This computes 33,000 \u00d7 0.8, incorrectly treating the interest as a deduction rather than solving for the original principal.", "misconceptionId": "overgeneralized_rule"}]$q$::jsonb, $q$techmed_authored$q$, $q$JAMB$q$, $q$A sum of money amounts to ₦33,000 after 2 years at 10% per annum simple interest. Find the principal.$q$, $q$[{"label": "A", "text": "\u20a625,000", "isCorrect": false}, {"label": "B", "text": "\u20a627,500", "isCorrect": true}, {"label": "C", "text": "\u20a630,000", "isCorrect": false}, {"label": "D", "text": "\u20a626,400", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$Amount = Principal × (1 + RT/100) = P × (1 + 0.20) = 1.2P. Setting 1.2P = 33,000 gives P = 33,000/1.2 = ₦27,500.$q$, $q$live$q$, $q$A: This divides 33,000 by an incorrect growth factor of 1.32 instead of 1.2. C: This assumes only 10% total growth instead of 20% (10% × 2 years). D: This computes 33,000 × 0.8, incorrectly treating the interest as a deduction rather than solving for the original principal.$q$),
($q$mathematics_0016$q$, $q$Mathematics$q$, $q$Mensuration$q$, $q$Area, Perimeter and Volume$q$, $q$Compute the area of a rectangle.$q$, $q$[{"conceptId": "1ui9n7", "weight": 1}]$q$::jsonb, 1, $q$recall$q$, 35, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "This adds the length and width instead of multiplying them \u2014 that relates to half the perimeter, not the area.", "misconceptionId": "formula_recall_error"}, {"option": "B", "explanation": "This is the perimeter of the rectangle (2\u00d7(12+7)=38), not the area.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "This doubles the correct area (2\u00d784=168).", "misconceptionId": "arithmetic_slip"}]$q$::jsonb, $q$techmed_authored$q$, $q$JAMB$q$, $q$Find the area of a rectangle with length 12 cm and width 7 cm.$q$, $q$[{"label": "A", "text": "19cm\u00b2", "isCorrect": false}, {"label": "B", "text": "38cm\u00b2", "isCorrect": false}, {"label": "C", "text": "84cm\u00b2", "isCorrect": true}, {"label": "D", "text": "168cm\u00b2", "isCorrect": false}]$q$::jsonb, $q$C$q$, $q$Area of a rectangle = length × width = 12 × 7 = 84 cm².$q$, $q$live$q$, $q$A: This adds the length and width instead of multiplying them — that relates to half the perimeter, not the area. B: This is the perimeter of the rectangle (2×(12+7)=38), not the area. D: This doubles the correct area (2×84=168).$q$),
($q$mathematics_0017$q$, $q$Mathematics$q$, $q$Mensuration$q$, $q$Area, Perimeter and Volume$q$, $q$Compute the circumference of a circle.$q$, $q$[{"conceptId": "1ui9n7", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 45, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "This uses C = \u03c0r instead of C = 2\u03c0r, missing the factor of 2.", "misconceptionId": "formula_recall_error"}, {"option": "C", "explanation": "This is the area of the circle (\u03c0r\u00b2 = (22/7)\u00d77\u00d77 = 154 cm\u00b2), not the circumference.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "This doubles the correct circumference (2\u00d744=88) with an extra unnecessary factor of 2.", "misconceptionId": "arithmetic_slip"}]$q$::jsonb, $q$techmed_authored$q$, $q$JAMB$q$, $q$Find the circumference of a circle of radius 7 cm. (Take π = 22/7)$q$, $q$[{"label": "A", "text": "22cm", "isCorrect": false}, {"label": "B", "text": "44cm", "isCorrect": true}, {"label": "C", "text": "154cm", "isCorrect": false}, {"label": "D", "text": "88cm", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$Circumference = 2πr = 2 × (22/7) × 7 = 44 cm.$q$, $q$live$q$, $q$A: This uses C = πr instead of C = 2πr, missing the factor of 2. C: This is the area of the circle (πr² = (22/7)×7×7 = 154 cm²), not the circumference. D: This doubles the correct circumference (2×44=88) with an extra unnecessary factor of 2.$q$),
($q$mathematics_0018$q$, $q$Mathematics$q$, $q$Mensuration$q$, $q$Area, Perimeter and Volume$q$, $q$Compute the volume of a cuboid.$q$, $q$[{"conceptId": "1ui9n7", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 45, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "This multiplies only two of the three dimensions (4\u00d73=12), leaving out the length.", "misconceptionId": "formula_recall_error"}, {"option": "C", "explanation": "This confuses a surface-area-style calculation with the volume formula \u2014 they use different combinations of the dimensions.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "This doubles the correct volume (2\u00d760=120).", "misconceptionId": "arithmetic_slip"}]$q$::jsonb, $q$techmed_authored$q$, $q$JAMB$q$, $q$A cuboid has length 5 cm, width 4 cm, and height 3 cm. Find its volume.$q$, $q$[{"label": "A", "text": "12cm\u00b3", "isCorrect": false}, {"label": "B", "text": "60cm\u00b3", "isCorrect": true}, {"label": "C", "text": "94cm\u00b3", "isCorrect": false}, {"label": "D", "text": "120cm\u00b3", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$Volume of a cuboid = length × width × height = 5 × 4 × 3 = 60 cm³.$q$, $q$live$q$, $q$A: This multiplies only two of the three dimensions (4×3=12), leaving out the length. C: This confuses a surface-area-style calculation with the volume formula — they use different combinations of the dimensions. D: This doubles the correct volume (2×60=120).$q$),
($q$mathematics_0019$q$, $q$Mathematics$q$, $q$Trigonometry$q$, $q$Right-Angled Triangles$q$, $q$Apply the definition of sine in a right-angled triangle.$q$, $q$[{"conceptId": "edgjx3", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 45, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "This uses the adjacent side (4 cm, found via Pythagoras) as the denominator instead of the hypotenuse \u2014 that ratio would be tan \u03b8, not sin \u03b8.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "This is cos \u03b8 (adjacent/hypotenuse = 4/5), not sin \u03b8.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "This inverts the ratio (hypotenuse/opposite) \u2014 the reciprocal of sin \u03b8, not sin \u03b8 itself.", "misconceptionId": "formula_recall_error"}]$q$::jsonb, $q$techmed_authored$q$, $q$JAMB$q$, $q$In a right-angled triangle, the side opposite angle θ is 3 cm and the hypotenuse is 5 cm. Find sin θ.$q$, $q$[{"label": "A", "text": "3/4", "isCorrect": false}, {"label": "B", "text": "3/5", "isCorrect": true}, {"label": "C", "text": "4/5", "isCorrect": false}, {"label": "D", "text": "5/3", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$sin θ = opposite/hypotenuse = 3/5.$q$, $q$live$q$, $q$A: This uses the adjacent side (4 cm, found via Pythagoras) as the denominator instead of the hypotenuse — that ratio would be tan θ, not sin θ. C: This is cos θ (adjacent/hypotenuse = 4/5), not sin θ. D: This inverts the ratio (hypotenuse/opposite) — the reciprocal of sin θ, not sin θ itself.$q$),
($q$mathematics_0020$q$, $q$Mathematics$q$, $q$Trigonometry$q$, $q$Right-Angled Triangles$q$, $q$Use sine to find an unknown side in a right-angled triangle word problem.$q$, $q$[{"conceptId": "edgjx3", "weight": 1}]$q$::jsonb, 3, $q$application$q$, 70, $q$medium$q$, $q$moderate$q$, $q$[{"option": "A", "explanation": "This uses sin 30\u00b0 (0.5) instead of sin 60\u00b0.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "This assumes the ladder reaches its full length up the wall, ignoring the angle entirely.", "misconceptionId": "misunderstood_terminology"}, {"option": "D", "explanation": "This divides by sin 60\u00b0 instead of multiplying (10/0.866\u224811.55).", "misconceptionId": "formula_recall_error"}]$q$::jsonb, $q$techmed_authored$q$, $q$JAMB$q$, $q$A ladder 10 m long leans against a wall, making an angle of 60° with the ground. Find the height it reaches on the wall. (sin 60° ≈ 0.866)$q$, $q$[{"label": "A", "text": "5m", "isCorrect": false}, {"label": "B", "text": "8.66m", "isCorrect": true}, {"label": "C", "text": "10m", "isCorrect": false}, {"label": "D", "text": "11.55m", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$Height = hypotenuse × sin θ = 10 × sin 60° = 10 × 0.866 = 8.66 m.$q$, $q$live$q$, $q$A: This uses sin 30° (0.5) instead of sin 60°. C: This assumes the ladder reaches its full length up the wall, ignoring the angle entirely. D: This divides by sin 60° instead of multiplying (10/0.866≈11.55).$q$),
($q$mathematics_0021$q$, $q$Mathematics$q$, $q$Trigonometry$q$, $q$Right-Angled Triangles$q$, $q$Recall standard trigonometric ratios for common angles.$q$, $q$[{"conceptId": "edgjx3", "weight": 1}]$q$::jsonb, 1, $q$recall$q$, 25, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "This is tan 0\u00b0, not tan 45\u00b0.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "This is the ratio between the hypotenuse and a leg in a 45-45-90 triangle (\u221a2:1), not the tangent ratio itself.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "This is tan 60\u00b0, not tan 45\u00b0.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$techmed_authored$q$, $q$JAMB$q$, $q$Find the value of tan 45°.$q$, $q$[{"label": "A", "text": "0", "isCorrect": false}, {"label": "B", "text": "1", "isCorrect": true}, {"label": "C", "text": "\u221a2", "isCorrect": false}, {"label": "D", "text": "\u221a3", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$In a right-angled triangle with a 45° angle, the opposite and adjacent sides are equal, so tan 45° = 1.$q$, $q$live$q$, $q$A: This is tan 0°, not tan 45°. C: This is the ratio between the hypotenuse and a leg in a 45-45-90 triangle (√2:1), not the tangent ratio itself. D: This is tan 60°, not tan 45°.$q$),
($q$mathematics_0022$q$, $q$Mathematics$q$, $q$Statistics$q$, $q$Measures of Central Tendency$q$, $q$Compute the mean of a small data set.$q$, $q$[{"conceptId": "p7l3z1", "weight": 1}]$q$::jsonb, 1, $q$recall$q$, 35, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "This is the median of the data set (arranged in order: 4,6,8,10,12), not the mean.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "This is one of the data values, not the computed mean.", "misconceptionId": "misunderstood_terminology"}, {"option": "D", "explanation": "This is the sum of the values \u2014 the division by 5 (the number of values) was left out.", "misconceptionId": "formula_recall_error"}]$q$::jsonb, $q$techmed_authored$q$, $q$JAMB$q$, $q$Find the mean of the numbers 4, 8, 6, 10, 12.$q$, $q$[{"label": "A", "text": "6", "isCorrect": false}, {"label": "B", "text": "8", "isCorrect": true}, {"label": "C", "text": "10", "isCorrect": false}, {"label": "D", "text": "40", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$Mean = sum of values ÷ number of values = (4+8+6+10+12)/5 = 40/5 = 8.$q$, $q$live$q$, $q$A: This is the median of the data set (arranged in order: 4,6,8,10,12), not the mean. C: This is one of the data values, not the computed mean. D: This is the sum of the values — the division by 5 (the number of values) was left out.$q$),
($q$mathematics_0023$q$, $q$Mathematics$q$, $q$Statistics$q$, $q$Measures of Central Tendency$q$, $q$Find the median of a data set with an even number of values.$q$, $q$[{"conceptId": "p7l3z1", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 45, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "This is only the lower of the two middle values, not their average.", "misconceptionId": "formula_recall_error"}, {"option": "C", "explanation": "This is only the upper of the two middle values, not their average.", "misconceptionId": "formula_recall_error"}, {"option": "D", "explanation": "This confuses the median process with a running total of the two middle values instead of their average.", "misconceptionId": "arithmetic_slip"}]$q$::jsonb, $q$techmed_authored$q$, $q$JAMB$q$, $q$Find the median of the numbers 7, 3, 9, 5, 11, 1.$q$, $q$[{"label": "A", "text": "5", "isCorrect": false}, {"label": "B", "text": "6", "isCorrect": true}, {"label": "C", "text": "7", "isCorrect": false}, {"label": "D", "text": "36", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$Arranged in order: 1, 3, 5, 7, 9, 11. With 6 values, the median is the average of the two middle values: (5+7)/2 = 6.$q$, $q$live$q$, $q$A: This is only the lower of the two middle values, not their average. C: This is only the upper of the two middle values, not their average. D: This confuses the median process with a running total of the two middle values instead of their average.$q$),
($q$mathematics_0024$q$, $q$Mathematics$q$, $q$Statistics$q$, $q$Measures of Central Tendency$q$, $q$Identify the mode of a data set.$q$, $q$[{"conceptId": "p7l3z1", "weight": 1}]$q$::jsonb, 1, $q$recall$q$, 35, $q$low$q$, $q$light$q$, $q$[{"option": "B", "explanation": "5 appears twice \u2014 more than most values, but fewer times than 4, so it is not the most frequent value.", "misconceptionId": "arithmetic_slip"}, {"option": "C", "explanation": "6 appears only once \u2014 it is not the most frequent value in the set.", "misconceptionId": "misunderstood_terminology"}, {"option": "D", "explanation": "This is the mean of the data set, not the mode.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$techmed_authored$q$, $q$JAMB$q$, $q$Find the mode of the data set: 2, 4, 4, 5, 6, 4, 7, 5.$q$, $q$[{"label": "A", "text": "4", "isCorrect": true}, {"label": "B", "text": "5", "isCorrect": false}, {"label": "C", "text": "6", "isCorrect": false}, {"label": "D", "text": "33/8", "isCorrect": false}]$q$::jsonb, $q$A$q$, $q$The mode is the value that occurs most often. 4 appears three times, more than any other value, so the mode is 4.$q$, $q$live$q$, $q$B: 5 appears twice — more than most values, but fewer times than 4, so it is not the most frequent value. C: 6 appears only once — it is not the most frequent value in the set. D: This is the mean of the data set, not the mode.$q$),
($q$mathematics_0025$q$, $q$Mathematics$q$, $q$Probability$q$, $q$Simple Probability$q$, $q$Compute the probability of a simple event from counted outcomes.$q$, $q$[{"conceptId": "otm0ur", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 45, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "This is the probability of picking a blue ball, not a red one.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "This compares red balls to blue balls (5:3) rather than red balls to the total number of balls.", "misconceptionId": "formula_recall_error"}, {"option": "D", "explanation": "This is the ratio of blue to red balls, not the probability of picking red from the total.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$techmed_authored$q$, $q$JAMB$q$, $q$A bag contains 5 red balls and 3 blue balls. Find the probability of picking a red ball at random.$q$, $q$[{"label": "A", "text": "3/8", "isCorrect": false}, {"label": "B", "text": "5/8", "isCorrect": true}, {"label": "C", "text": "5/3", "isCorrect": false}, {"label": "D", "text": "3/5", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$Probability = number of favorable outcomes / total outcomes = 5/(5+3) = 5/8.$q$, $q$live$q$, $q$A: This is the probability of picking a blue ball, not a red one. C: This compares red balls to blue balls (5:3) rather than red balls to the total number of balls. D: This is the ratio of blue to red balls, not the probability of picking red from the total.$q$),
($q$mathematics_0026$q$, $q$Mathematics$q$, $q$Probability$q$, $q$Simple Probability$q$, $q$Compute the probability of an event on a single die roll.$q$, $q$[{"conceptId": "otm0ur", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 45, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "This counts only one favorable outcome instead of two (5 and 6 both qualify).", "misconceptionId": "formula_recall_error"}, {"option": "C", "explanation": "This corresponds to 3 favorable outcomes out of 6, but only 5 and 6 (not 4) are greater than 4.", "misconceptionId": "misunderstood_terminology"}, {"option": "D", "explanation": "This corresponds to 4 favorable outcomes out of 6 \u2014 too many numbers were counted as 'greater than 4.'", "misconceptionId": "arithmetic_slip"}]$q$::jsonb, $q$techmed_authored$q$, $q$JAMB$q$, $q$A fair die is rolled once. Find the probability of obtaining a number greater than 4.$q$, $q$[{"label": "A", "text": "1/6", "isCorrect": false}, {"label": "B", "text": "1/3", "isCorrect": true}, {"label": "C", "text": "1/2", "isCorrect": false}, {"label": "D", "text": "2/3", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$Numbers greater than 4 on a die are 5 and 6 — 2 favorable outcomes out of 6 total, giving 2/6 = 1/3.$q$, $q$live$q$, $q$A: This counts only one favorable outcome instead of two (5 and 6 both qualify). C: This corresponds to 3 favorable outcomes out of 6, but only 5 and 6 (not 4) are greater than 4. D: This corresponds to 4 favorable outcomes out of 6 — too many numbers were counted as 'greater than 4.'$q$),
($q$mathematics_0027$q$, $q$Mathematics$q$, $q$Probability$q$, $q$Simple Probability$q$, $q$Enumerate outcomes for two independent events and compute a compound probability.$q$, $q$[{"conceptId": "otm0ur", "weight": 1}]$q$::jsonb, 3, $q$application$q$, 55, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "This counts only one of the two outcomes with exactly one head (HT or TH alone).", "misconceptionId": "formula_recall_error"}, {"option": "C", "explanation": "This includes HH as an 'exactly one head' outcome, but HH has two heads, not one.", "misconceptionId": "misunderstood_terminology"}, {"option": "D", "explanation": "This assumes getting exactly one head is certain, but TT and HH are also possible outcomes.", "misconceptionId": "overgeneralized_rule"}]$q$::jsonb, $q$techmed_authored$q$, $q$JAMB$q$, $q$Two fair coins are tossed together. Find the probability of getting exactly one head.$q$, $q$[{"label": "A", "text": "1/4", "isCorrect": false}, {"label": "B", "text": "1/2", "isCorrect": true}, {"label": "C", "text": "3/4", "isCorrect": false}, {"label": "D", "text": "1", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$The possible outcomes are HH, HT, TH, TT. Exactly one head occurs in 2 of these (HT, TH), giving a probability of 2/4 = 1/2.$q$, $q$live$q$, $q$A: This counts only one of the two outcomes with exactly one head (HT or TH alone). C: This includes HH as an 'exactly one head' outcome, but HH has two heads, not one. D: This assumes getting exactly one head is certain, but TT and HH are also possible outcomes.$q$),
($q$mathematics_0028$q$, $q$Mathematics$q$, $q$Sequences and Series$q$, $q$Arithmetic and Geometric Progression$q$, $q$Find a specified term of an arithmetic progression.$q$, $q$[{"conceptId": "j8p7et", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 50, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "This uses (n\u22121)=8 instead of 9 in the formula, effectively finding the 9th term.", "misconceptionId": "arithmetic_slip"}, {"option": "C", "explanation": "This uses (n\u22121)=10 instead of 9 in the formula, effectively finding the 11th term.", "misconceptionId": "arithmetic_slip"}, {"option": "D", "explanation": "This multiplies the term number directly by the common difference (10\u00d73) instead of applying the AP formula.", "misconceptionId": "formula_recall_error"}]$q$::jsonb, $q$techmed_authored$q$, $q$JAMB$q$, $q$Find the 10th term of the arithmetic progression 3, 7, 11, 15, ...$q$, $q$[{"label": "A", "text": "35", "isCorrect": false}, {"label": "B", "text": "39", "isCorrect": true}, {"label": "C", "text": "43", "isCorrect": false}, {"label": "D", "text": "30", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$For an AP, Tₙ = a + (n−1)d. Here a=3, d=4, n=10: T₁₀ = 3 + (9×4) = 3 + 36 = 39.$q$, $q$live$q$, $q$A: This uses (n−1)=8 instead of 9 in the formula, effectively finding the 9th term. C: This uses (n−1)=10 instead of 9 in the formula, effectively finding the 11th term. D: This multiplies the term number directly by the common difference (10×3) instead of applying the AP formula.$q$),
($q$mathematics_0029$q$, $q$Mathematics$q$, $q$Sequences and Series$q$, $q$Arithmetic and Geometric Progression$q$, $q$Find the sum of the first n terms of an arithmetic progression.$q$, $q$[{"conceptId": "j8p7et", "weight": 1}]$q$::jsonb, 3, $q$application$q$, 75, $q$low$q$, $q$moderate$q$, $q$[{"option": "A", "explanation": "An arithmetic slip in evaluating [2a+(n\u22121)d] gives 23 instead of 25, leading to 4\u00d723=92.", "misconceptionId": "arithmetic_slip"}, {"option": "C", "explanation": "This uses (n\u22121)=9 instead of 7 inside the bracket, effectively computing one term too many.", "misconceptionId": "formula_recall_error"}, {"option": "D", "explanation": "This uses n/2=4 correctly but multiplies by an incorrect bracket value of 22 instead of 25.", "misconceptionId": "arithmetic_slip"}]$q$::jsonb, $q$techmed_authored$q$, $q$JAMB$q$, $q$Find the sum of the first 8 terms of the arithmetic progression 2, 5, 8, 11, ...$q$, $q$[{"label": "A", "text": "92", "isCorrect": false}, {"label": "B", "text": "100", "isCorrect": true}, {"label": "C", "text": "108", "isCorrect": false}, {"label": "D", "text": "88", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$Sₙ = n/2 × [2a + (n−1)d]. Here a=2, d=3, n=8: S₈ = 4 × [4 + 21] = 4 × 25 = 100.$q$, $q$live$q$, $q$A: An arithmetic slip in evaluating [2a+(n−1)d] gives 23 instead of 25, leading to 4×23=92. C: This uses (n−1)=9 instead of 7 inside the bracket, effectively computing one term too many. D: This uses n/2=4 correctly but multiplies by an incorrect bracket value of 22 instead of 25.$q$),
($q$mathematics_0030$q$, $q$Mathematics$q$, $q$Sequences and Series$q$, $q$Arithmetic and Geometric Progression$q$, $q$Find a specified term of a geometric progression.$q$, $q$[{"conceptId": "j8p7et", "weight": 1}]$q$::jsonb, 3, $q$application$q$, 70, $q$low$q$, $q$moderate$q$, $q$[{"option": "A", "explanation": "This uses r^(n\u22121)=2\u00b3 instead of 2\u2074, effectively finding the 4th term.", "misconceptionId": "arithmetic_slip"}, {"option": "C", "explanation": "This uses r^(n\u22121)=2\u2075 instead of 2\u2074, effectively finding the 6th term.", "misconceptionId": "arithmetic_slip"}, {"option": "D", "explanation": "This treats the sequence as arithmetic (adding a fixed amount) rather than geometric, instead of multiplying by the common ratio.", "misconceptionId": "overgeneralized_rule"}]$q$::jsonb, $q$techmed_authored$q$, $q$JAMB$q$, $q$The first term of a geometric progression is 3 and the common ratio is 2. Find the 5th term.$q$, $q$[{"label": "A", "text": "24", "isCorrect": false}, {"label": "B", "text": "48", "isCorrect": true}, {"label": "C", "text": "96", "isCorrect": false}, {"label": "D", "text": "15", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$For a GP, Tₙ = a×r^(n−1). Here a=3, r=2, n=5: T₅ = 3×2⁴ = 3×16 = 48.$q$, $q$live$q$, $q$A: This uses r^(n−1)=2³ instead of 2⁴, effectively finding the 4th term. C: This uses r^(n−1)=2⁵ instead of 2⁴, effectively finding the 6th term. D: This treats the sequence as arithmetic (adding a fixed amount) rather than geometric, instead of multiplying by the common ratio.$q$);
